import math


class Group:
    def __init__(self, members: list[str]) -> None:
        self.members = list(members)
        self._members_set = set(members)
        # Track balances internally in integer cents to avoid floating-point errors
        self._balances_cents: dict[str, int] = {m: 0 for m in self.members}

    def add_expense(
        self,
        payer: str,
        amount: float,
        participants: list[str] | None = None,
    ) -> None:
        """Record that `payer` paid `amount` on behalf of `participants`."""
        if amount <= 0:
            raise ValueError("Amount must be greater than zero.")

        if payer not in self._members_set:
            raise ValueError(f"Payer '{payer}' is not a group member.")

        if participants is None:
            actual_participants = list(self.members)
        else:
            actual_participants = list(participants)

        if not actual_participants:
            raise ValueError("Participants list cannot be empty.")

        for p in actual_participants:
            if p not in self._members_set:
                raise ValueError(f"Participant '{p}' is not a group member.")

        total_cents = round(amount * 100)
        n = len(actual_participants)

        # Each participant (other than payer handling the remainder) owes amount rounded down to the cent
        base_share_cents = total_cents // n
        remainder_cents = total_cents % n

        # Payer credited the total amount paid
        self._balances_cents[payer] += total_cents

        if payer in actual_participants:
            # Other participants pay base_share_cents
            # Payer owes base_share_cents + remainder_cents for their own share
            for p in actual_participants:
                if p == payer:
                    self._balances_cents[p] -= (base_share_cents + remainder_cents)
                else:
                    self._balances_cents[p] -= base_share_cents
        else:
            # Payer is not among the participants; the leftover cents are borne by the payer
            # Non-payer participants pay base_share_cents
            # Payer absorbs remainder_cents
            for p in actual_participants:
                self._balances_cents[p] -= base_share_cents
            self._balances_cents[payer] -= remainder_cents

    def balances(self) -> dict[str, float]:
        """Net balance per member. Positive = the member is owed money,
        negative = the member owes money."""
        return {m: self._balances_cents[m] / 100.0 for m in self.members}

    def settle_up(self) -> list[tuple[str, str, float]]:
        """Payments that settle the group, as (debtor, creditor, amount)."""
        debtors: list[list] = []  # [member, cents_owed (positive)]
        creditors: list[list] = []  # [member, cents_owed_to (positive)]

        for m in self.members:
            cents = self._balances_cents[m]
            if cents < 0:
                debtors.append([m, -cents])
            elif cents > 0:
                creditors.append([m, cents])

        payments: list[tuple[str, str, float]] = []
        d_idx = 0
        c_idx = 0

        while d_idx < len(debtors) and c_idx < len(creditors):
            debtor, d_cents = debtors[d_idx]
            creditor, c_cents = creditors[c_idx]

            transfer = min(d_cents, c_cents)
            if transfer >= 100:  # Payments must be at least 1.00 (100 cents)
                payments.append((debtor, creditor, transfer / 100.0))

            debtors[d_idx][1] -= transfer
            creditors[c_idx][1] -= transfer

            if debtors[d_idx][1] == 0:
                d_idx += 1
            if creditors[c_idx][1] == 0:
                c_idx += 1

        return payments
